#pragma once
// Annotation mode V3-B — the dithered textures (pure: no HWND, no Direct2D, no clock reads).
// Paper « MCP - Design UI UX », section 5 (5.1 « Entrée du mode — pic du dégradé », 5.2 « Bandeau vivant »), validated
// by the user on 14 November 2026. The reference textures were generated by gen_dither.py (scratchpad of the design
// task): ordered dithering with the 4x4 Bayer matrix, one dot per cell, the last pixel row/column of a cell left empty
// (« point » look). Cells: 2 DIP in the band, 3 DIP over the page. The formulas below are that script's, in DIP:
//   band   crest = H (0.55 + 0.30 sin(2π (x/210 − φ)))       band = exp(−((y − crest)/5.5)²)
//          env   = exp(−((x/W − c(φ))/0.22)²)                  base = 0.18 y/H
//          v     = base + 0.85 band (0.35 + 0.65 env) · amp · mask(x)
//   page   top = max(0, 1 − y/260)^1.8   edge = 0.7 max(0, 1 − d/110)², d = min(x, W − x, H − y)
//          v   = max(top, edge) (1 + 0.22 sin(x/70 + y/38 − ωt)) 0.95 · k
// A dot is drawn where v > (Bayer + 0.5)/16, in #3E67FF at alpha 150 (band) / 120 (page), or the bright tone above 0.75.
// Two deliberate changes to the script, both needed by the motion and the user's correction:
//   - c(φ): the script moved the envelope from 0.15 W to 0.85 W and jumped back at the end of each pass; the loop
//     here is seamless (the envelope travels one full width per 4 s pass, wrapped: c = 0.15 + φ modulo 1).
//   - mask(x): the wave never passes under a text (user's correction of 5.2): a smoothstep fade of 120 DIP down to 0
//     before « Mode Annotation » (+ BETA), before « Quitter / Échap » and under the reminder when it shows. The zones
//     come from the real label rectangles (LayoutBanner), never from constants. The base texture stays everywhere.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <vector>

namespace NativeChrome { namespace Annotations { namespace Dither {
inline constexpr int bayer[4][4] = {{0, 8, 2, 10}, {12, 4, 14, 6}, {3, 11, 1, 9}, {15, 7, 13, 5}};
inline float Threshold(int cx, int cy) noexcept { return (bayer[cy & 3][cx & 3] + .5f) / 16.f; }
inline float Clamp01(float v) noexcept { return v < 0 ? 0.f : v > 1 ? 1.f : v; }
inline float Smoothstep(float e0, float e1, float x) noexcept { const float t = Clamp01((x - e0) / (e1 - e0)); return t * t * (3 - 2 * t); }

// ---------------------------------------------------------------- the band's wave (Paper 5.2)
namespace Wave {
inline constexpr double period = 4.0;          // s per pass, linear
inline constexpr int startMs = 220;            // after the entry: the band has landed
inline constexpr int riseMs = 400;             // the band's amplitude grows from 0 (no pop at 220 ms)
inline constexpr int fps = 30;                 // at most
inline constexpr float fade = 120;             // DIP of smoothstep before a text
inline constexpr float cell = 2, opacity = .85f;   // Paper « Vague tramée »: opacity 0.85
inline constexpr std::uint32_t dim = 0x3E67FF96, bright = 0x7FA0FFDC;   // RGBA (gen_dither.py: (62,103,255,150), (127,160,255,220))
}
// The text-free span of the band [left, right] (DIP): the wave is 0 outside it and fades in over Wave::fade inside.
struct Zones { float left = 0, right = 0; };
inline float Mask(float x, const Zones& z) noexcept {
    if (z.right - z.left <= 0) return 0;
    return Smoothstep(z.left, z.left + Wave::fade, x) * Smoothstep(z.right, z.right - Wave::fade, x);
}
// φ in [0, 1): the position in the 4 s loop.
inline double Phase(double seconds) noexcept { const double p = std::fmod(seconds / Wave::period, 1.0); return p < 0 ? p + 1 : p; }
// The wave's own part (band × envelope), before the mask and amplitude.
inline float WaveBand(float x, float y, float w, float h, double phase) noexcept {
    const float crest = h * (.55f + .30f * float(std::sin(6.283185307179586 * (x / 210.0 - phase))));
    const float b = (y - crest) / 5.5f, band = std::exp(-b * b);
    double d = x / std::max(w, 1.f) - (.15 + phase); d -= std::floor(d + .5);   // wrapped: seamless loop
    const float e = float(d / .22), env = std::exp(-e * e);
    return .85f * band * (.35f + .65f * env);
}
inline float BandField(float x, float y, float w, float h, double phase, float amp, const Zones& z) noexcept {
    const float base = .18f * Clamp01(y / std::max(h, 1.f));
    if (amp <= 0) return base;
    const float m = Mask(x, z); if (m <= 0) return base;
    return base + WaveBand(x, y, w, h, phase) * amp * m;
}
// The amplitude at `ms` after the entry: 0 before 220 ms, then an ease-out rise over 400 ms. Reduced motion: 0.
inline float Amplitude(double ms, bool reduced) noexcept {
    if (reduced || ms <= Wave::startMs) return 0;
    const float t = Clamp01(float((ms - Wave::startMs) / Wave::riseMs)); return 1 - (1 - t) * (1 - t);
}

// ---------------------------------------------------------------- the entry veil (Paper 5.1, track « Dégradé » of 5.2)
namespace Veil {
inline constexpr int riseMs = 140, holdMs = 80, endMs = 500, exitMs = 160;   // up 0-140, held to 220, out by 500
inline constexpr int reducedMs = 150; inline constexpr float reducedPeak = .5f;  // reduced: no texture, 50 %, 150 ms fades
inline constexpr float topDip = 160;             // the wash falls 160 DIP from the band (Paper: #3E67FF33 -> 0 at 22 % of 698)
inline constexpr float topAlpha = .2f;           // #3E67FF33
inline constexpr float rimAlpha = 56 / 255.f;    // inset 0 0 48px #3E67FF38 (left, right, bottom)
inline constexpr float rimBlur = 48;             // CSS blur radius: sigma = 24
inline constexpr float cell = 3;
inline constexpr double wobble = 6.0;            // rad/s: the texture ripples during the 500 ms
inline constexpr std::uint32_t dim = 0x3E67FF78, bright = 0x3E67FFBE;   // (62,103,255,120), (62,103,255,190)
}
inline float EaseOut(float t) noexcept { t = Clamp01(t); return 1 - (1 - t) * (1 - t) * (1 - t); }
inline float EaseInOut(float t) noexcept { t = Clamp01(t); return t < .5f ? 4 * t * t * t : 1 - std::pow(-2 * t + 2, 3.f) / 2; }
// The veil's intensity over time; an exit during the entry fades it from the value on screen (interruptible).
class VeilTimeline {
    bool reduced_ = false, out_ = false; double outAt_ = 0, outFrom_ = 0;
public:
    void Start(bool reduced) noexcept { reduced_ = reduced; out_ = false; }
    bool Reduced() const noexcept { return reduced_; }
    bool Interrupted() const noexcept { return out_; }
    float Natural(double ms) const noexcept {
        if (ms <= 0) return 0;
        if (reduced_) return ms < Veil::reducedMs ? Veil::reducedPeak * EaseOut(float(ms / Veil::reducedMs))
                                                  : Veil::reducedPeak * (1 - EaseInOut(float((ms - Veil::reducedMs) / Veil::reducedMs)));
        if (ms < Veil::riseMs) return EaseOut(float(ms / Veil::riseMs));
        if (ms < Veil::riseMs + Veil::holdMs) return 1;
        return 1 - EaseInOut(float((ms - Veil::riseMs - Veil::holdMs) / (Veil::endMs - Veil::riseMs - Veil::holdMs)));
    }
    double EndMs() const noexcept { return out_ ? outAt_ + (reduced_ ? Veil::reducedMs : Veil::exitMs) : reduced_ ? 2.0 * Veil::reducedMs : Veil::endMs; }
    // The mode ends at `ms`: from the presented value down to 0 (160 ms; reduced 150 ms).
    void Interrupt(double ms) noexcept { if (out_) return; outFrom_ = Value(ms); outAt_ = ms; out_ = true; }
    float Value(double ms) const noexcept {
        if (!out_ || ms <= outAt_) return Clamp01(Natural(ms));
        const double len = reduced_ ? Veil::reducedMs : Veil::exitMs;
        return float(outFrom_) * (1 - EaseOut(float((ms - outAt_) / len)));
    }
    bool Done(double ms) const noexcept { return ms >= EndMs(); }
};
// The page field at intensity k (0..1).
inline float VeilField(float x, float y, float w, float h, double seconds, float k) noexcept {
    const float top = std::pow(std::max(0.f, 1 - y / 260.f), 1.8f);
    const float d = std::min(std::min(x, w - x), h - y), e = std::max(0.f, 1 - d / 110.f), edge = e * e * .7f;
    const float wave = 1 + .22f * float(std::sin(x / 70.0 + y / 38.0 - Veil::wobble * seconds));
    return std::max(top, edge) * wave * .95f * k;
}
// erfc approximation (Abramowitz-Stegun 7.1.26, |error| < 1.5e-7).
inline double Erfc(double x) noexcept {
    const double z = std::fabs(x), t = 1 / (1 + .3275911 * z);
    const double y = t * (.254829592 + t * (-.284496736 + t * (1.421413741 + t * (-1.453152027 + t * 1.061405429)))) * std::exp(-z * z);
    return x >= 0 ? y : 2 - y;
}
// The inset rim's alpha at `d` DIP from the edge (a CSS inset shadow, blur 48 => Gaussian sigma 24).
inline float RimAlpha(float d) noexcept { return float(Veil::rimAlpha * .5 * Erfc(d / (Veil::rimBlur / 2 * 1.4142135623730951))); }
inline float WashAlpha(float y) noexcept { return Veil::topAlpha * Clamp01(1 - y / Veil::topDip); }

// ---------------------------------------------------------------- rasters (premultiplied BGRA, top-down)
struct Raster { std::uint32_t* px = nullptr; int stride = 0, w = 0, h = 0; };   // stride in pixels
inline std::uint32_t Premul(std::uint32_t rgba, float alpha) noexcept {
    const float a = Clamp01(((rgba & 255) / 255.f) * alpha);
    const auto c = [&](int shift) { return std::uint32_t(std::lround(((rgba >> shift) & 255) * a)); };
    return (std::uint32_t(std::lround(a * 255)) << 24) | (c(24) << 16) | (c(16) << 8) | c(8);
}
inline std::uint32_t Over(std::uint32_t src, std::uint32_t dst) noexcept {   // premultiplied src-over
    const std::uint32_t sa = src >> 24; if (sa == 255 || !dst) return src; if (!sa) return dst;
    const auto ch = [&](int shift) { return ((src >> shift) & 255) + (((dst >> shift) & 255) * (255 - sa) + 127) / 255; };
    return (ch(24) << 24) | (ch(16) << 16) | (ch(8) << 8) | ch(0);
}
// Cells snapped to device pixels: crisp dots at every scale (2 DIP at 125 % = 3 px cell, 2 px dot).
inline int CellPx(float dip, float scale) noexcept { return std::max(2, int(std::lround(dip * scale))); }
inline int GapPx(float scale) noexcept { return std::max(1, int(std::lround(scale))); }
// The band's texture over the whole band (transparent elsewhere): base + wave, Wave::opacity applied.
inline int RasterBand(const Raster& r, float scale, double seconds, float amp, const Zones& z) {
    const int cp = CellPx(Wave::cell, scale), dot = cp - GapPx(scale); int dots = 0;
    const float w = r.w / scale, h = r.h / scale; const double phase = Phase(seconds);
    const std::uint32_t dim = Premul(Wave::dim, Wave::opacity), bright = Premul(Wave::bright, Wave::opacity);
    for (int y = 0; y < r.h; ++y) std::fill_n(r.px + size_t(y) * r.stride, r.w, 0u);
    for (int cy = 0; cy * cp < r.h; ++cy) for (int cx = 0; cx * cp < r.w; ++cx) {
        const float x = (cx + .5f) * cp / scale, y = (cy + .5f) * cp / scale;
        const float v = BandField(x, y, w, h, phase, amp, z);
        if (v <= Threshold(cx, cy)) continue;
        const std::uint32_t c = v < .75f ? dim : bright; ++dots;
        for (int py = cy * cp; py < std::min(r.h, cy * cp + dot); ++py) std::fill_n(r.px + size_t(py) * r.stride + cx * cp, std::min(dot, r.w - cx * cp), c);
    }
    return dots;
}
// The veil over the page at intensity k: wash from the top + rim on the three other sides, then the texture.
// `r` must come zeroed (the live layer clears its surface): the page's middle, transparent, is never touched — a
// full-page frame costs the top band, the three rims and the texture cells only.
inline void RasterVeil(const Raster& r, float scale, double seconds, float k, bool texture) {
    const float w = r.w / scale, h = r.h / scale;
    if (k <= 0) return;
    const int rimPx = std::min(int(std::ceil(Veil::rimBlur * 2 * scale)) + 1, std::max(1, r.w / 2));
    static thread_local std::vector<float> rim; rim.assign(size_t(rimPx), 0);
    for (int d = 0; d < rimPx; ++d) rim[size_t(d)] = RimAlpha((d + .5f) / scale);
    static thread_local std::uint32_t lut[256];   // alpha byte -> premultiplied #3E67FF
    for (int i = 0; i < 256; ++i) lut[i] = (std::uint32_t(i) << 24) | (std::uint32_t((62 * i + 127) / 255) << 16) | (std::uint32_t((103 * i + 127) / 255) << 8) | std::uint32_t(i);
    const int washRows = std::min(r.h, int(std::ceil(Veil::topDip * scale)) + 1);
    auto pixel = [&](float wash, float side) -> std::uint32_t { const int a = int((1 - (1 - wash) * (1 - side)) * k * 255 + .5f); return a > 0 ? lut[std::min(a, 255)] : 0u; };
    for (int y = 0; y < r.h; ++y) {
        std::uint32_t* row = r.px + size_t(y) * r.stride;
        const float wash = y < washRows ? WashAlpha((y + .5f) / scale) : 0.f; const int fromBottom = r.h - 1 - y;
        const float bottom = fromBottom < rimPx ? rim[size_t(fromBottom)] : 0;
        if (wash <= 0 && bottom <= 0) {   // only the two side rims
            for (int x = 0; x < rimPx; ++x) { const std::uint32_t p = pixel(0, rim[size_t(x)]); row[x] = p; row[r.w - 1 - x] = p; }
            continue;
        }
        for (int x = 0; x < r.w; ++x) {
            const int side = std::min(x, r.w - 1 - x);
            row[x] = pixel(wash, std::max(bottom, side < rimPx ? rim[size_t(side)] : 0.f));
        }
    }
    if (!texture) return;
    const int cp = CellPx(Veil::cell, scale), dot = cp - GapPx(scale);
    const std::uint32_t dim = Premul(Veil::dim, 1), bright = Premul(Veil::bright, 1);
    // VeilField, separated: top(y) per row, the ripple sin(x/70 + y/38 - wt) = sin(a)cos(b) + cos(a)sin(b) from
    // per-column and per-row tables (same values, no pow / sin per cell).
    const int cols = (r.w + cp - 1) / cp;
    static thread_local std::vector<float> sx, cx_, ex;
    sx.resize(size_t(cols)); cx_.resize(size_t(cols)); ex.resize(size_t(cols));
    for (int c = 0; c < cols; ++c) { const double x = (c + .5) * cp / scale; sx[size_t(c)] = float(std::sin(x / 70.0)); cx_[size_t(c)] = float(std::cos(x / 70.0)); ex[size_t(c)] = float(std::min(x, double(w) - x)); }
    for (int cy = 0; cy * cp < r.h; ++cy) {
        const float y = (cy + .5f) * cp / scale;
        const float top = y < 260 ? std::pow(1 - y / 260.f, 1.8f) : 0.f;
        const double b = y / 38.0 - Veil::wobble * seconds; const float sb = float(std::sin(b)), cb = float(std::cos(b)), bottomD = h - y;
        for (int cx = 0; cx * cp < r.w; ++cx) {
            const float x = (cx + .5f) * cp / scale;
            if (y > 260 && std::min(std::min(x, w - x), h - y) > 110) { const int skip = int((w - 110) * scale / cp) - cx - 1; if (skip > 0) cx += skip; continue; }
            const float d = std::min(ex[size_t(cx)], bottomD), e = std::max(0.f, 1 - d / 110.f);
            const float v = std::max(top, e * e * .7f) * (1 + .22f * (sx[size_t(cx)] * cb + cx_[size_t(cx)] * sb)) * .95f * k;
            if (v <= Threshold(cx, cy)) continue;
            const std::uint32_t c = v < .75f ? dim : bright;
            for (int py = cy * cp; py < std::min(r.h, cy * cp + dot); ++py) { std::uint32_t* p = r.px + size_t(py) * r.stride; for (int px = cx * cp; px < std::min(r.w, cx * cp + dot); ++px) p[px] = Over(c, p[px]); }
        }
    }
}

// ---------------------------------------------------------------- the mode's cursor (Paper 5.4, direction A « flèche + note »)
// SVG 32x32, hot spot = the arrow's tip (5, 3). Sizes 32 / 48 / 64 px from the display scale x the Windows pointer size
// (HKCU\Control Panel\Cursors\CursorBaseSize, 32 by default): the nearest of the three, at or above 1.25 => 48,
// at or above 1.75 => 64.
namespace Cursor {
inline constexpr int hotX = 5, hotY = 3;
inline const char* Svg() {
    return "<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'>"
           "<path d='M5 3 L5 24 L10.2 19.4 L13.6 27.2 L17 25.7 L13.7 18.1 L20.6 18.1 Z' fill='#1C1C1C' stroke='#FFFFFF' stroke-width='1.5' stroke-linejoin='round'/>"
           "<circle cx='23.5' cy='23.5' r='6.5' fill='#3E67FF' stroke='#FFFFFF' stroke-width='1.5'/>"
           "<path d='M23.5 20.5 V26.5 M20.5 23.5 H26.5' fill='none' stroke='#FFFFFF' stroke-width='1.6' stroke-linecap='round'/></svg>";
}
inline int SizeFor(unsigned dpi, unsigned baseSize) noexcept {
    const double f = (dpi ? dpi : 96) / 96.0 * (baseSize >= 16 && baseSize <= 512 ? baseSize : 32) / 32.0;
    return f >= 1.75 ? 64 : f >= 1.25 ? 48 : 32;
}
}
}}} // namespace NativeChrome::Annotations::Dither
